INSERT INTO `examples` VALUES (1,4,'我是学生。','wǒ shì xuéshēng 。','Tôi là học sinh.','tự biên soạn','我 是 学生 。'),(2,7,'他不是老师。','tā bú shì lǎoshī 。','Anh ấy không phải là giáo viên.','tự biên soạn','他 不 是 老师 。'),(3,108,'你叫什么名字?','nǐ jiào shénme míngzì ?','Bạn tên là gì?','tự biên soạn','你 叫 什么 名字 ?'),(4,234,'我的名字是小明。','wǒ de míngzì shì xiǎomíng 。','Tên tôi là Tiểu Minh.','tự biên soạn','我 的 名字 是 小明 。'),(5,170,'很高兴认识你。','hěn gāoxìng rènshí nǐ 。','Rất vui được biết bạn.','tự biên soạn','很 高兴 认识 你 。'),(6,161,'我喜欢喝茶。','wǒ xǐhuān hē chá 。','Tôi thích uống trà.','tự biên soạn','我 喜欢 喝 茶 。'),(7,8,'我有一个哥哥。','wǒ yǒu yí gè gēgē 。','Tôi có một người anh trai.','tự biên soạn','我 有 一 个 哥哥 。'),(8,34,'我没有钱。','wǒ méiyǒu qián 。','Tôi không có tiền.','tự biên soạn','我 没有 钱 。'),(9,6,'他在家。','tā zài jiā 。','Anh ấy ở nhà.','tự biên soạn','他 在 家 。'),(10,29,'我们明天去北京。','wǒmen míngtiān qù běijīng 。','Ngày mai chúng tôi đi Bắc Kinh.','tự biên soạn','我们 明天 去 北京 。'),(11,26,'请你来我家。','qǐng nǐ lái wǒ jiā 。','Mời bạn đến nhà tôi.','tự biên soạn','请 你 来 我 家 。'),(12,82,'我想吃米饭。','wǒ xiǎng chī mǐfàn 。','Tôi muốn ăn cơm.','tự biên soạn','我 想 吃 米饭 。'),(13,32,'你想喝什么?','nǐ xiǎng hē shénme ?','Bạn muốn uống gì?','tự biên soạn','你 想 喝 什么 ?'),(14,38,'我喜欢看电影。','wǒ xǐhuān kàn diànyǐng 。','Tôi thích xem phim.','tự biên soạn','我 喜欢 看 电影 。'),(15,105,'她喜欢听音乐。','tā xǐhuān tīng yīnyuè 。','Cô ấy thích nghe nhạc.','tự biên soạn','她 喜欢 听 音乐 。'),(16,15,'他会说汉语。','tā huì shuō hànyǔ 。','Anh ấy biết nói tiếng Hán.','tự biên soạn','他 会 说 汉语 。'),(17,20,'我会游泳。','wǒ huì yóuyǒng 。','Tôi biết bơi.','tự biên soạn','我 会 游泳 。'),(18,35,'你能帮我吗?','nǐ néng bāng wǒ ma ?','Bạn có thể giúp tôi không?','tự biên soạn','你 能 帮 我 吗 ?'),(19,119,'我想买一本书。','wǒ xiǎng mǎi yì běn shū 。','Tôi muốn mua một quyển sách.','tự biên soạn','我 想 买 一 本 书 。'),(20,114,'这本书很好看。','zhè běn shū hěn hǎokàn 。','Quyển sách này rất hay.','tự biên soạn','这 本 书 很 好看 。'),(21,182,'这个多少钱?','zhè ge duōshǎo qián ?','Cái này bao nhiêu tiền?','tự biên soạn','这 个 多少 钱 ?'),(22,99,'你家有几口