  `meaning_vi` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  KEY `grammar_examples_grammar_id_idx` (`grammar_id`),
  CONSTRAINT `grammar_examples_grammar_id_fkey` FOREIGN KEY (`grammar_id`) REFERENCES `grammar_points` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=85 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
