CREATE TABLE `grammar_points` (
  `id` int NOT NULL AUTO_INCREMENT,
  `level` int NOT NULL,
  `sort_order` int NOT NULL,
  `title` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `pattern` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `explanation` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  KEY `grammar_points_level_idx` (`level`)
) ENGINE=InnoDB AUTO_INCREMENT=40 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `grammar_points`
--

LOCK TABLES `grammar_points` WRITE;
/*!40000 ALTER TABLE `grammar_points` DISABLE KEYS */;
INSERT INTO `grammar_points` VALUES (1,1,1,'Câu chữ 是 (shì)','Chủ ngữ + 是 + danh từ','Dùng 是 để nối chủ ngữ với danh từ, tương đương \"là\" trong tiếng Việt. Phủ định là 不是.','Trước tính từ không dùng 是: nói 她很高, không nói 她是高.'),(2,1,2,'Câu hỏi với 吗 (ma)','Câu trần thuật + 吗 ?','Thêm 吗 vào cuối câu trần thuật để tạo câu hỏi có/không. Trả lời bằng cách lặp lại động từ hoặc dùng 不.','Không dùng 吗 cùng lúc với từ để hỏi như 什么, 谁.'),(3,1,3,'Phủ định với 不 và 没','不 + động từ / tính từ ;  没(有) + động từ','不 phủ định thói quen, ý muốn, tương lai và tính từ. 没 phủ định việc đã xảy ra hoặc chưa xảy ra trong quá khứ, và phủ định của 有 là 没有.','Không nói 不有, phải nói 没有.'),(4,1,4,'Câu chữ 有 (yǒu)','Chủ ngữ + 有 + tân ngữ','有 biểu thị sở hữu hoặc tồn tại, nghĩa là \"có\". Phủ định là 没有.',NULL),(5,1,5,'Trợ từ 的 (de) chỉ sở hữu','Định ngữ + 的 + trung tâm ngữ','的 nối từ chỉ sở hữu hoặc tính chất với danh từ, giống \"của\". Với quan hệ rất thân thiết (gia đình) hoặc tổ chức có thể lược 的.','Có thể nói 我的书, còn 我妈妈 thường lược 的.'),(6,1,6,'Đại từ nghi vấn','Dùng 什么, 谁, 哪, 几, 多少, 怎么 đúng vị trí của thành phần cần hỏi','Trong tiếng Trung, từ để hỏi đứng đúng vị trí của câu trả lời, không cần đảo trật tự câu. Không thêm 吗.','几 hỏi số lượng nhỏ (dưới 10), 多少 hỏi số lượng bất kỳ.'),(7,1,7,'Lượng từ','Số từ + lượng từ + danh từ','Giữa số từ và danh từ phải có lượng từ. 个 là lượng từ phổ biến nhất, 本 dùng cho sách, 杯 cho cốc đồ uống. Khi đếm số lượng thì dùng 两 thay cho 二.','Nói 两个人, không nói 二个人.'),(8,1,8,'Giới từ 在 chỉ nơi chốn','Chủ ngữ + 在 + địa điểm + động từ','在 đứng trước địa điểm và đứng trước động từ để chỉ nơi xảy ra hành động. 在 cũng có thể là động từ nghĩa là \"ở\".',NULL),(9,1,9,'Trạng từ 很 trước tính từ','Chủ ngữ + 很 + tính từ','Tính từ làm vị ngữ thường đi với 很 (không nhất thiết mang nghĩa \"rất\"). Không dùng 是 trước tính từ.',NULL),(10,1,10,'Trạng từ 也 và 都','Chủ ngữ + 也 / 都 + động từ','也 nghĩa là \"cũng\", 都 nghĩa là \"đều\". Cả hai đứng trước động từ hoặc tính từ. Khi dùng chung thì 也 đứng trước 都.',NULL),(11,1,11,'Trợ từ 了 (le) chỉ hoàn thành','Động từ + 了 (+ tân ngữ) ;  Câu + 了','了 sau động từ nói hành động đã hoàn thành. 了 cuối câu nói sự việc đã thay đổi hoặc có trạng thái mới.','Phủ định hoàn thành dùng 没, và bỏ 了: 我没吃早饭.'),(12,1,12,'Câu hỏi chính phản','Động từ + 不 + động từ ?','Lặp lại động từ hoặc tính từ ở dạng khẳng định + phủ định để hỏi. Mang nghĩa \"có ... không\".','Không dùng thêm 吗 trong dạng câu hỏi này.'),(13,1,13,'Động từ năng nguyện 想, 会, 能, 可以','Chủ ngữ + 想 / 会 / 能 / 可以 + động từ','想: muốn. 会: biết (do học được) hoặc sẽ. 能: có thể (khả năng, điều kiện). 可以: được phép. Phủ định thường là 不想, 不会, 不能, 不可以.',NULL),(14,1,14,'Câu hỏi rút gọn với 呢 (ne)','Danh từ / đại từ + 呢 ?','Dùng 呢 để hỏi lại cùng một câu hỏi cho đối tượng khác, nghĩa là \"còn ... thì sao\".',NULL),(15,1,15,'Cách nói giờ giấc','Số + 点 (+ số + 分) ;  半 ;  刻','Giờ nói là 点, phút là 分. 半 là rưỡi (30 phút), 一刻 là 15 phút. Thời gian đứng trước động từ.','Thời gian đứng trước động từ: 我八点去学校, không nói 我去学校八点.'),(16,2,16,'Trợ từ 过 (guo) chỉ kinh nghiệm','Động từ + 过','过 đứng sau động từ để nói đã từng làm việc gì trong quá khứ. Phủ định là 没 + động từ + 过.',NULL),(17,2,17,'正在 / 在 chỉ hành động đang diễn ra','Chủ ngữ + 正在 / 在 + động từ (+ 呢)','正在 hoặc 在 đứng trước động từ để nói hành động đang tiến hành, có thể thêm 呢 cuối câu. Phủ định là 没在 + động từ.',NULL),(18,2,18,'So sánh bằng 比','A + 比 + B + tính từ (+ số lượng)','Dùng 比 để so sánh hơn. Trước tính từ không dùng 很. Muốn nói rõ chênh lệch thì thêm sau tính từ, ví dụ 一点儿 hoặc 三岁. Phủ định là A + 没有 + B + tính từ.','Không nói 他比我很高.'),(19,2,19,'Bổ ngữ trạng thái với 得 (de)','Động từ + 得 + tính từ','得 nối động từ với phần mô tả mức độ hoặc cách thức của hành động. Nếu có tân ngữ thì lặp lại động từ: 说汉语说得很好.',NULL),(20,2,20,'还是 và 或者','A 还是 B ?  ;  A 或者 B','还是 dùng trong câu hỏi lựa chọn (\"hay là\"). 或者 dùng trong câu trần thuật (\"hoặc\").',NULL),(21,2,21,'因为 ... 所以 ...','因为 + nguyên nhân , 所以 + kết quả','Biểu thị quan hệ nguyên nhân kết quả. Khác tiếng Việt, tiếng Trung thường dùng cả hai từ cùng lúc.',NULL),(22,2,22,'虽然 ... 但是 ...','虽然 + vế nhượng bộ , 但是 + vế chính','Biểu thị sự đối lập: \"tuy ... nhưng ...\". Trong tiếng Trung bắt buộc dùng 但是 (hoặc 可是) ở vế sau.',NULL),(23,2,23,'Sắp xảy ra: 要 ... 了 / 快 ... 了','要 / 快 + động từ / tính từ + 了','Biểu thị sự việc sắp xảy ra. 快 và 就要 đều có thể dùng, nhưng khi có thời điểm cụ thể thì chỉ dùng 就要.',NULL),(24,2,24,'离, 从 ... 到 ...','A + 离 + B + khoảng cách ;  从 + A + 到 + B','离 nói khoảng cách giữa hai điểm hoặc hai thời điểm. 从 ... 到 ... nói điểm xuất phát đến điểm đích hoặc khoảng thời gian.',NULL),(25,2,25,'Câu liên động','Chủ ngữ + 去 / 来 + địa điểm + động từ','Hai hành động liên tiếp của cùng một chủ ngữ được đặt cạnh nhau, không cần từ nối. Hành động xảy ra trước đứng trước.',NULL),(26,2,26,'一点儿 và 有点儿','Tính từ + 一点儿 ;  有点儿 + tính từ','一点儿 đứng sau tính từ, dùng khi so sánh hoặc đề nghị. 有点儿 đứng trước tính từ, thường mang sắc thái không hài lòng.',NULL),(27,2,27,'再 và 又','再 + động từ (sẽ lặp lại) ;  又 + động từ (đã lặp lại)','再 nói hành động sẽ lặp lại trong tương lai. 又 nói hành động đã lặp lại trong quá khứ.',NULL),(28,3,28,'Câu chữ 把 (bǎ)','Chủ ngữ + 把 + tân ngữ + động từ + thành phần khác','Dùng 把 để đưa tân ngữ ra trước động từ, nhấn mạnh cách tân ngữ bị xử lý hoặc thay đổi. Sau động từ phải có thành phần khác như 了, bổ ngữ kết quả hoặc xu hướng. Tân ngữ sau 把 phải xác định.','Không nói 我把书看, vì thiếu thành phần sau động từ.'),(29,3,29,'Câu bị động với 被 (bèi)','Chủ ngữ (người/vật chịu tác động) + 被 + người gây ra + động từ + thành phần khác','被 đưa đối tượng chịu tác động lên làm chủ ngữ. Người gây ra hành động có thể được lược bỏ. Động từ sau 被 thường kèm 了 hoặc bổ ngữ.',NULL),(30,3,30,'如果 ... 就 ...','如果 + điều kiện , (主语) + 就 + kết quả','Biểu thị giả thiết: \"nếu ... thì ...\". 就 ở vế sau đứng trước động từ.',NULL),(31,3,31,'越 ... 越 ...','越 + động từ / tính từ 1 , 越 + động từ / tính từ 2','Diễn tả mức độ ở vế sau tăng theo vế trước: \"càng ... càng ...\".',NULL),(32,3,32,'一 ... 就 ...','一 + động từ 1 , 就 + động từ 2','Hai hành động xảy ra liên tiếp, hoặc điều kiện vừa thỏa là kết quả xảy ra ngay: \"vừa ... là ...\".',NULL),(33,3,33,'Bổ ngữ khả năng','Động từ + 得 / 不 + bổ ngữ kết quả hoặc xu hướng','Cho biết có thể hay không thể hoàn thành hành động. Khẳng định dùng 得, phủ định dùng 不. Ví dụ 听得懂 (nghe hiểu được) và 听不懂 (nghe không hiểu).',NULL),(34,3,34,'Bổ ngữ xu hướng','Động từ + 上 / 下 / 进 / 出 / 回 / 过 / 起 + 来 / 去','Chỉ hướng di chuyển của hành động. 来 là hướng về phía người nói, 去 là hướng ra xa người nói.',NULL),(35,3,35,'Câu 是 ... 的','是 + thời gian / nơi chốn / cách thức + động từ + 的','Dùng để nhấn mạnh thời gian, địa điểm hoặc cách thức của hành động đã xảy ra rồi. 是 có thể lược bỏ trong câu khẳng định.',NULL),(36,3,36,'除了 ... 以外','除了 + A + 以外 , 都 / 还 / 也 ...','Nếu đi với 都 thì loại trừ A (ngoài A ra thì đều ...). Nếu đi với 还 hoặc 也 thì bổ sung thêm (ngoài A ra còn ...).',NULL),(37,3,37,'不但 ... 而且 ...','不但 + vế 1 , 而且 + vế 2 (+ 也 / 还)','Biểu thị tăng tiến: \"không những ... mà còn ...\".',NULL),(38,3,38,'就 và 才','时间 + 就 + động từ + 了 ;  时间 + 才 + động từ','就 nhấn mạnh sự việc xảy ra sớm, nhanh, thuận lợi. 才 nhấn mạnh sự việc xảy ra muộn, chậm hoặc khó khăn.',NULL),(39,3,39,'Trợ từ 着 (zhe)','Động từ + 着','着 sau động từ biểu thị trạng thái đang kéo dài, ví dụ 开着 (đang mở), 坐着 (đang ngồi).',NULL);
