INSERT INTO `words` VALUES (1,'的','的','de','của; ~(hậu tố sở hữu); (dùng sau định ngữ); (dùng để tạo thành cụm danh từ)','of; ~\'s (possessive particle); (used after an attribute); (used to form a nominal expression); (used at the end of a declarative sentence for emphasis)','u,n','Đích',1,1,1,'白','https://api.wohuimandarin.com/nls/tts?text=de'),(2,'了','了','le','(trợ từ chỉ hành động đã hoàn thành); (trợ từ ngữ khí nhấn mạnh mệnh đề đứng trước)','(completed action marker); (modal particle indicating change of state, situation now); (modal particle intensifying preceding clause)','y,u,v','Liễu',1,1,3,'亅','https://api.wohuimandarin.com/nls/tts?text=le'),(3,'我','我','wǒ','tôi; mình; của tôi','I; me; my','r','Ngã',1,1,3,'戈','https://api.wohuimandarin.com/nls/tts?text=w%C7%92'),(4,'是','是','shì','là (chỉ theo sau bởi danh từ); đúng; phải; thật; sự thừa nhận tôn kính một mệnh lệnh: rất tốt','to be (followed by substantives only); correct; right; true; (respectful acknowledgement of a command) very well; (adverb for emphatic assertion)','v','Thị',1,1,4,'日','https://api.wohuimandarin.com/nls/tts?text=sh%C3%AC'),(5,'你','你','nǐ','bạn','you (informal, as opposed to courteous 您)','r','Nhĩ',1,1,5,'亻','https://api.wohuimandarin.com/nls/tts?text=n%C7%90'),(6,'在','在','zài','tồn tại; còn sống; (ai đó hoặc cái gì đó) ở (vị trí)','to exist; to be alive; (of sb or sth) to be (located) at; (used before a verb to indicate an action in progress)','p,v,d','Tại',1,1,5,'土','https://api.wohuimandarin.com/nls/tts?text=z%C3%A0i'),(7,'不','不','bù','không; không phải; (hình thức kết hợp) không; bất','no; not so; (bound form) not; un-','d','Bất',1,1,9,'一','https://api.wohuimandarin.com/nls/tts?text=b%C3%B9'),(8,'有','有','yǒu','có; có (gì đó); (dạng kết hợp) có; với; mang tính chất gì đó','to have; there is; (bound form) having; with; -ful; -ed; -al (as in 意 intentional)','v','Hữu',1,1,9,'月','https://api.wohuimandarin.com/nls/tts?text=y%C7%92u'),(9,'他','他','tā','anh ấy; ông ấy; (dùng trước tên ai đó để